--
-- Table structure for table `pantallas`
--

DROP TABLE IF EXISTS `pantallas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pantallas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cuenta_id` int NOT NULL,
  `contacto` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nro_pantalla` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_compra` date NOT NULL,
  `fecha_vencimiento` date NOT NULL,
  `meses_pagados` int DEFAULT '0',
  `total_pagado` decimal(10,2) DEFAULT '0.00',
  `estado` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `comentario` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `total_ganado` decimal(18,2) DEFAULT NULL,
  `total_pagado_proveedor` decimal(18,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_pantalla_contacto` (`contacto`),
  KEY `fk_pantalla_cuenta` (`cuenta_id`),
  CONSTRAINT `fk_pantalla_contacto` FOREIGN KEY (`contacto`) REFERENCES `usuarios` (`contacto`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pantalla_cuenta` FOREIGN KEY (`cuenta_id`) REFERENCES `cuentascompartidas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=433 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

